function canAttendAll(meetings: number[][]): boolean {
  const m = meetings.map(x => [x[0], x[1]]).sort((a, b) => a[0] - b[0]);
  for (let i = 1; i < m.length; i++) if (m[i][0] < m[i - 1][1]) return false;
  return true;
}

